insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('62cc1680-aeca-4531-9946-53d98465573e', 'N2', '普通形 ＋ とか', 'Thấy bảo hình như là... (nghe nói, truyền đạt lại thông tin không chắc chắn)', NULL, '普通形 ＋ とか', 'Truyền đạt lại thông tin nghe được từ người khác mà bản thân không chắc chắn', NULL, NULL, NULL, '{}', NULL, 63, '普通形 ＋ とか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8c2610ae-dde7-428c-baaa-048775750da1', 'N2', 'Vていく／Vてくる', '① Diễn tả hành động rồi tiếp tục diễn biến/di chuyển xa dần　② Diễn tả trạng thái/hành động đã diễn ra liên tục đến hiện tại　③ Diễn tả sự thay đổi dần dần của 1 trạng thái mới　④ Chỉ hướng của hành động từ điểm nhìn người nói　⑤ Diễn tả sự xuất hiện bất ngờ của 1 trạng thái mới', NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 63, 'Vていく／Vてくる', 'pdf', 'ok')
