insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('1c83676e-9dcb-4f8d-b465-21a043e1dae8', 'N2', 'Vる／Vた ＋ か＋Vない＋かのうちに', 'Ngay khi vừa mới...thì... (chưa rõ đã xong hay chưa đã xảy ra việc tiếp theo)', NULL, 'Vる／Vた ＋ か ＋ Vない ＋ かのうちに', 'Diễn tả việc thứ 2 xảy ra ngay khi việc thứ nhất còn chưa hoàn tất rõ ràng', NULL, NULL, NULL, '{}', NULL, 63, 'Vる／Vた ＋ か＋Vない＋かのうちに', 'pdf', 'ok')
