insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('8c2610ae-dde7-428c-baaa-048775750da1', '9627836e-7014-45ab-a897-701f797475fd', 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Diễn tả trạng thái/hành động đã diễn ra liên tục cho tới thời điểm nói"?', 'Vていく／Vてくる', 'V(普)／Aい(普)／Aな／Aなである／N(である) ＋ だけに', 'Vば／Aければ／Aなであれば／Nであれば ＋ こそ', 'Vます ＋ がたい', 'Vていく／Vてくる', 'generated');
