insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('367824bf-c6e3-4e63-b45a-74e2a620a9e3', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Chính vì... nên mới... (nhấn mạnh lý do chính đáng, duy nhất dẫn đến hành động/kết quả)"?', 'V(普)／Aい(普)／Aな／Aなである／N(である) ＋ だけに', 'Vば／Aければ／Aなであれば／Nであれば ＋ こそ', 'V普通形／Aな／N(である) ＋ だけあって', '普通形 ＋ とか', 'Vば／Aければ／Aなであれば／Nであれば ＋ こそ', 'generated');
